async def act(page):
    """
    From the current page state, navigate to the Sample Page (if available), locate the visible search widget,
    search for 'diabetes', and click the bottom-most result. All interactions use accessibility-role-centric
    selectors and await locator.count() before using .nth(). The final click is the last action.
    """
    # 1) Attempt to navigate to the Sample Page by clicking its link if present
    try:
        sample_links = page.get_by_role("link", name="Sample Page")
        if await sample_links.count() > 0:
            await sample_links.nth(0).click()
            # wait for navigation/load to settle
            try:
                await page.wait_for_load_state("networkidle")
            except Exception:
                try:
                    await page.wait_for_load_state("load")
                except Exception:
                    # give a short pause as a last resort
                    import asyncio
                    await asyncio.sleep(1)
    except Exception:
        # If clicking Sample Page fails, proceed with current page (maybe search exists here)
        pass

    # 2) Locate a search input, preferring complementary region's searchbox/textbox
    search_input = None
    try:
        # Try complementary region first
        comp = page.get_by_role("complementary")
        if await comp.count() > 0:
            comp_region = comp.nth(0)
            if await comp_region.get_by_role("searchbox").count() > 0:
                search_input = comp_region.get_by_role("searchbox").nth(0)
            elif await comp_region.get_by_role("textbox").count() > 0:
                search_input = comp_region.get_by_role("textbox").nth(0)
    except Exception:
        search_input = None

    # 3) Global fallbacks if complementary region didn't yield an input
    if search_input is None:
        try:
            if await page.get_by_role("searchbox").count() > 0:
                search_input = page.get_by_role("searchbox").nth(0)
            elif await page.get_by_role("textbox").count() > 0:
                search_input = page.get_by_role("textbox").nth(0)
        except Exception:
            search_input = None

    # If still no search input, we cannot perform the requested search
    if search_input is None:
        return

    # 4) Fill the search input with the desired keyword
    try:
        await search_input.fill("diabetes")
    except Exception:
        # If fill fails, try type
        try:
            await search_input.type("diabetes")
        except Exception:
            return

    # 5) Activate the search: prefer a Search-named button inside the complementary region
    activated = False
    try:
        # If we have a complementary region, try its buttons
        comp_now = page.get_by_role("complementary")
        if await comp_now.count() > 0:
            comp_now = comp_now.nth(0)
            # Try a button with visible name including 'Search' (case-sensitive match with name param is case-insensitive)
            if await comp_now.get_by_role("button", name="Search").count() > 0:
                await comp_now.get_by_role("button", name="Search").nth(0).click()
                activated = True
            else:
                # pragmatic fallback: click the first button inside the complementary region
                if await comp_now.get_by_role("button").count() > 0:
                    await comp_now.get_by_role("button").nth(0).click()
                    activated = True
        # If not activated yet, try a global Search-labeled button
        if not activated:
            if await page.get_by_role("button", name="Search").count() > 0:
                await page.get_by_role("button", name="Search").nth(0).click()
                activated = True
    except Exception:
        activated = False

    # Last resort: press Enter inside the input
    if not activated:
        try:
            await search_input.press("Enter")
            activated = True
        except Exception:
            # give up if we cannot trigger search
            return

    # 6) Wait for results container role="main" to be visible (with fallback)
    main = page.get_by_role("main")
    try:
        await main.wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            # small pause in case of client-side rendering
            import asyncio
            await asyncio.sleep(1)

    # 7) Locate article children inside main; fallback to page-level articles
    articles = None
    try:
        if await main.count() > 0 and await main.get_by_role("article").count() > 0:
            articles = main.get_by_role("article")
        elif await page.get_by_role("article").count() > 0:
            articles = page.get_by_role("article")
    except Exception:
        # if role queries fail, nothing more to do
        return

    if articles is None:
        return

    article_count = await articles.count()
    if article_count == 0:
        return

    # 8) Click the bottom-most article's first link if present, else click the article element itself
    last_article = articles.nth(article_count - 1)
    try:
        if await last_article.get_by_role("link").count() > 0:
            await last_article.get_by_role("link").nth(0).click()
        else:
            await last_article.click()
    except Exception:
        # final attempt: click the article element directly
        try:
            await last_article.click()
        except Exception:
            return

